// Example policy mapper (pseudo)
function mapCKNEToPolicy(ckne){
  const epsilon = 0.1 + ckne * 0.9;
  const scope = ckne < 0.5 ? 'aggregate' : 'country_time';
  return {epsilon, scope};
}
```

